from lib import *
S = SS('g1')
def tail(lines, sub):
    i = [k for k, l in enumerate(lines) if sub in l][0]
    return lines[i:]
L1 = tail(S(1), '编译器诊断')
steps = [
    step("九个函数各写一种分配方式,全部标 //go:noinline,用 go build -gcflags=-m 读编译器的结论(Go 1.27.1)。returnPtr 返回 &p:moved to heap: p;toInterface 把 p 传给 fmt.Fprintln:p escapes to heap;closure 的变量 x 被返回的闭包捕获:moved to heap: x,闭包本身 func literal escapes to heap;byValue 不取地址,没有任何逃逸诊断;make([]int, 10)、make([]int, n)(n 是参数)、make([]int, 8000) 都是 does not escape;make([]int, 8200) 与 var a [1 << 20]int 分别是 escapes to heap 与 moved to heap: a。", t=tl(L1), done=lidx(L1, 'returnPtr', 'toInterface', 'closure'), mark=lidx(L1, 'make([]int, 8200)', 'moved to heap: a'), kv=KV([['moved to heap: p', 'returnPtr:返回了 &p'], ['p escapes to heap', 'toInterface:传给 ...any 参数'], ['moved to heap: x', 'closure:被返回的闭包捕获'], ['make([]int, 8000)', 'does not escape(64000 字节)'], ['make([]int, 8200)', 'escapes to heap(65600 字节)'], ['var a [1 << 20]int', 'moved to heap: a(8 MiB)']], ['make([]int, 8200)'])),
    step("-m 的结论不等于运行时一定有分配,用 testing.AllocsPerRun(1000 次取平均)数真实次数:byValue 0、returnPtr 1、closure 2(x 一次、闭包本身一次);toInterface 虽然说 p escapes to heap,实测 0 次,因为 Point{1,2} 是常量,编译器直接指向只读数据;换成运行时才知道的值 ifacePoint(n=1000) 就是 1 次;int 转接口 n=255 是 0 次、n=256 是 1 次。变长 make:n=4(32 字节)0 次、n=5(40 字节)1 次;加 -gcflags=-d=variablemakethreshold=1024,n=64(512 字节)也是 0 次、n=1000 仍是 1 次;加 -N 关掉优化后 varMake(n=1) 变成 1 次。", t=tl(S(2)), done=lidx(S(2), 'byValue ', 'returnPtr ', 'closure(', 'toInterface(常量'), mark=lidx(S(2), 'ifaceInt(n=255)', 'ifaceInt(n=256)', 'varMake n=4(', 'varMake n=5(', 'variablemakethreshold', '-N'), b=bars([['varMake n=4 (32B)', 0, '0 次'], ['varMake n=5 (40B)', 1, '1 次'], ['阈值调到 1024:n=64', 0, '0 次'], ['阈值调到 1024:n=1000', 1, '1 次']], 1, done=[0, 2], mark=[1, 3]), kv=KV([['toInterface 常量 Point{1,2}', '0 次(尽管 -m 说 escapes to heap)'], ['ifacePoint(n=1000)', '1 次'], ['ifaceInt n=255 / 256', '0 次 / 1 次'], ['varMake n=4 / n=5', '0 次 / 1 次'], ['-d=variablemakethreshold=1024', 'n=64 也是 0 次'], ['-N', 'varMake(n=1) 变成 1 次']], ['varMake n=4 / n=5'])),
    step("栈上能放多大:用二分法反复编译、读 -m,找最大不被放到堆上的字节数。显式声明的局部数组 var a [N]byte:131072 字节(128 KiB)仍在栈上,131073 字节被放到堆上;make([]byte, N)(常量长度)、new([N]byte)、&[N]byte{} 三种隐式分配:65536 字节(64 KiB)仍在栈上,65537 字节被放到堆上。这与编译器源码 ir/cfg.go 里的 MaxStackVarSize = 128 * 1024 和 MaxImplicitStackVarSize = 64 * 1024 吻合。", t=tl(S(3)), done=lidx(S(3), 'var a [N]byte', 'make([]byte, N)', 'new([N]byte)', '&[N]byte{}'), b=bars([['var a [N]byte(KiB)', 128, '128'], ['make / new / &T{}(KiB)', 64, '64']], 128, done=[0, 1]), kv=KV([['var a [N]byte', '131072 字节在栈上,131073 在堆上'], ['make([]byte, N)', '65536 在栈上,65537 在堆上'], ['new([N]byte)', '65536 / 65537'], ['&[N]byte{}', '65536 / 65537']], ['var a [N]byte'])),
    step("-gcflags=\"-m -m\" 会多打印一条 flow 链,写明“谁的地址流向了哪里”。returnPtr:flow: ~r0 ← &p,来自 return &p,~r0 是返回值,所以 p 必须活得比函数长;toInterface:p 先装进 ...any 的临时存储,再作为调用参数流向 {heap};closure:x 被闭包引用(captured by a closure),闭包又被返回;make65k:{heap} ← &{storage for make([]int, 8200)},原因写的是 too large for stack。", t=tl(S(4)), done=lidx(S(4), 'returnPtr(', 'toInterface(', 'closure(', 'make65k('), mark=lidx(S(4), 'flow: ~r0 ← &p', 'flow: {heap}', 'captured by a closure', 'too large for stack'), kv=KV([['flow: ~r0 ← &p', '返回值拿着 p 的地址'], ['flow: {heap} ← ...', '参数流向堆(接口参数)'], ['captured by a closure', '闭包引用了 x'], ['too large for stack', 'make([]int, 8200) 超过 64 KiB']], ['flow: ~r0 ← &p'])),
    step("逃逸不是变量的固有属性,取决于上下文。newPoint 返回 &Point{1, 2}:在 newPoint 自己的诊断里永远是 &Point{...} escapes to heap;但默认编译时它被内联进 sum(inlining call to newPoint),在 sum 里同一个值变成 &Point{...} does not escape,sum() 每次调用 0 次分配;加 -gcflags=-l 关掉内联后,sum 里没有了这条诊断,sum() 每次调用 1 次分配。", t=tl(S(5)), done=lidx(S(5), '默认', 'sum() 每次调用的分配次数:0'), mark=lidx(S(5), '-gcflags=-l', 'sum() 每次调用的分配次数:1', 'inlining call to newPoint'), b=bars([['默认(内联):sum() 分配次数', 0, '0'], ['-l(不内联):sum() 分配次数', 1, '1']], 1, done=[0], mark=[1]), kv=KV([['newPoint 自己的诊断', '&Point{...} escapes to heap'], ['内联进 sum 之后', '&Point{...} does not escape'], ['默认 sum()', '0 次分配'], ['-gcflags=-l 的 sum()', '1 次分配']], ['内联进 sum 之后'])),
    step("代价:同一个循环调用 500 万次(每个变体重复 5 轮,取中位数)。byValue 留在栈上:耗时中位 10.1 ms(最小 9.7、最大 12.9),Mallocs 只增加 2,TotalAlloc 增加 80 字节,GC 0 次;returnPtr 逃到堆上:中位 33.3 ms(最小 33.0、最大 33.8),Mallocs 增加 5000003,TotalAlloc 增加 80000288 字节(每次 16 字节),这一轮里 GC 触发了 21 次。同一段代码里,逃逸让耗时约为原来的 3.3 倍。", t=tl(S(6)), done=lidx(S(6), 'byValue(栈)'), mark=lidx(S(6), 'returnPtr(堆)'), b=bars([['byValue(栈)ms', 10.1, '10.1'], ['returnPtr(堆)ms', 33.3, '33.3']], 33.3, done=[0], mark=[1]), kv=KV([['byValue(栈)', '10.1 ms / 0 次 GC / +80 字节'], ['returnPtr(堆)', '33.3 ms / 21 次 GC / +80000288 字节'], ['每次逃逸分配', '16 字节(Point 两个 int)'], ['耗时比', '约 3.3 倍']], ['returnPtr(堆)'])),
]
A = mkartg('g1', 1, 'Go,逃逸分析,编译器,内存分配,真实验证,动画演示',
    '用 Go 1.27.1 的 -gcflags=-m 与 -m -m 看编译器的逃逸判断,用 testing.AllocsPerRun 数真实分配次数:常量转接口虽然说 escapes to heap 却是 0 次分配,变长 make 在 32 字节以内留在栈上,二分法量出显式局部变量 128 KiB 与隐式分配 64 KiB 的栈上限,同一个函数内联与否结论相反,以及逃到堆上 500 万次比留在栈上慢约 3.3 倍。',
    '一个变量放在栈上还是堆上,不由 new 或者 &T{} 这样的写法决定,而是由编译器的逃逸分析决定。这篇先读 -m 的诊断,再用 AllocsPerRun 数出真实的分配次数,发现两者并不总是一致;然后量出栈上限、对照内联的影响,最后量一量逃逸到底多花多少。',
    [('128 KiB / 64 KiB', '显式局部变量 / 隐式分配(make、new、&T{})能留在栈上的上限(二分法实测)'), ('32 字节', '变长 make 的栈上缓冲:n=4 个 int 零分配,n=5 个就分配 1 次'), ('3.3 倍', '同样调用 500 万次,逃到堆上的 33.3 ms,留在栈上的 10.1 ms')],
    [('九种写法的逃逸结论', '<p>编译器的措辞有三种:<code>moved to heap: p</code> 说的是变量 p 本身被搬到堆上;<code>… escapes to heap</code> 说的是某个表达式的值(<code>make</code> 的结果、转成接口的值、函数字面量)要放在堆上;<code>does not escape</code> 是留在栈上。第 17 行的 <code>p escapes to heap</code> 说的是“把 p 转成接口这一步”,它并不等于运行时一定有一次分配,下一节会看到。</p>'),
     ('真实分配次数:-m 说逃逸,运行时不一定分配', '<p>三个出乎意料的结果。<b>第一</b>,<code>toInterface</code> 传的是常量 <code>Point{1,2}</code>,编译器直接指向只读数据,0 次分配;换成运行时才知道的值就是 1 次。我在编译器源码 <code>walk/convert.go</code> 里读到同一个函数的几个分支:零大小用 <code>zerobase</code>、单字节或布尔用 <code>staticuint64s</code> 表、只读全局直接用,最后才调用运行时分配。int 的 255 / 256 分界来自 <code>runtime/iface.go</code> 的 <code>convT64</code>:值小于 <code>len(staticuint64s)</code>(256)时直接取表项,否则调 <code>mallocgc</code>,实测与之一致。<b>第二</b>,变长 <code>make([]int, n)</code> 的诊断是 <code>does not escape</code>,但并不保证零分配:源码(<code>walk/builtin.go</code> 的 <code>walkMakeSlice</code> 与 <code>base/flag.go</code> 里的 <code>VariableMakeThreshold = 32</code>)写的是“如果 cap ≤ K,就用栈上的 [K]E,否则调 makeslice”,K 由 32 字节除以元素大小得到——int 是 8 字节,所以 K = 4,实测正是 n=4 零分配、n=5 一次分配。<b>第三</b>,<code>-d=variablemakethreshold=1024</code> 把阈值调大后 n=64 也是零分配,<code>-N</code> 关闭优化后变长 make 就回到一次分配,而常量长度的 <code>make(10)</code> 在 <code>-N</code> 下仍是零。</p>'),
     ('栈上能放多大', '<p>数字和源码里的两个常量对得上:<code>ir/cfg.go</code> 里 <code>MaxStackVarSize</code> 是 128 KiB(显式的 <code>var x T</code>),<code>MaxImplicitStackVarSize</code> 是 64 KiB(<code>new(T)</code>、<code>&T{}</code>、<code>make([]T, n)</code>)。二分法的结果是恰好以字节为界:131072 与 65536 在栈上,多一个字节就去了堆。注意这里是 arm64 上 Go 1.27.1 的数字,其它版本的上限可能不同。</p>'),
     ('flow 链:编译器为什么这么判断', '<p><code>-m -m</code> 的 flow 链从右往左读:<code>flow: ~r0 ← &p</code> 是“返回值 ~r0 取得了 p 的地址”,所以 p 的生命周期要超过函数。接口参数那条链里出现了 <code>{heap}</code>,意思是它流进了编译器无法证明不逃逸的调用(<code>fmt.Fprintln</code> 的 <code>...any</code> 参数)。<code>too large for stack</code> 是大小原因,不涉及数据流。看到 <code>moved to heap</code> 时,往上找 flow 链里第一个“address-of”和最后一个流向,就能定位是哪一行造成的。</p>'),
     ('同一段代码内联与否结论相反', '<p>逃逸分析是在函数边界上做的。<code>newPoint</code> 返回指针,在它自己的诊断里永远逃逸;但被内联进 <code>sum</code> 之后,指针没有离开 <code>sum</code>,这个值就留在了栈上。所以排查分配问题时,<code>-gcflags=-l</code> 能帮你分辨“这次分配是不是只因为某个调用没被内联”。</p>'),
     ('逃逸的代价', '<p>代价有两层:每次调用多一次 <code>mallocgc</code>(这里 16 字节),以及这些堆对象带来的 GC 工作。上面的 33.3 ms 里包含了这 21 次 GC 的成本,不能全算成分配本身。byValue 每次调用约 2 纳秒(10.1 ms / 500 万),这是 <code>//go:noinline</code> 函数调用本身的量级;不要把“3.3 倍”套到别的程序上,它只说明在这个最小例子里,逃逸把一次几乎没有成本的调用变成了一次分配加回收。</p>')],
    steps,
    [ENV_G + '。逃逸诊断与阈值均在 arm64 上用 Go 1.27.1 实测;读过的编译器源码在 brew 安装目录 libexec/src/cmd/compile/internal 下:ir/cfg.go(两个栈上限常量)、walk/convert.go(接口转换的免分配分支)、walk/builtin.go 与 base/flag.go(变长 make 的 K 与 32 字节阈值)、escape/utils.go 与 escape/escape.go(变长 make 的“混合”做法、把静态已知的长度改写成字面量);耗时是 5 轮取中位数,每次运行会有抖动',
     '没有验证:amd64 与 32 位平台上的栈上限和变长 make 阈值、Go 1.27 以前的版本是否有变长 make 的栈缓冲、-race / -msan 下的逃逸结论、cgo 指针传递规则、栈增长(大栈帧会触发复制整个栈)的代价、泛型函数的逃逸分析,以及 GC 触发节奏本身(见后面的 GC 相关文章)'],
    '逃逸分析')
